<map version="1.0.1"><node CREATED="1747229394309" ID="ID_root" MODIFIED="1747229394309" TEXT="目录流"><node CREATED="1747229394309" ID="ID_cffdce92f4b4c48d" POSITION="right" MODIFIED="1747229394309" TEXT="流"><node CREATED="1747229394309" ID="ID_a32a032690de1183" MODIFIED="1747229394309" TEXT="就是一个简化的编程模型。&amp;nbsp;比如，我们在操作文件的时候，我们只用关心，打开流&amp;lt;br&amp;gt;然后使用这个流读数据。&amp;nbsp;不断的读，读到的就是下一个数据。&amp;nbsp;&amp;lt;br&amp;gt;等到流中的数据读完之后，我们的所有数据也读完了&amp;lt;br&amp;gt;"></node><node CREATED="1747229394309" ID="ID_1bb9f4600fde065f" MODIFIED="1747229394309" TEXT="目录流：&amp;nbsp;就是用来读取目录信息的。首先打开流，读取流。&amp;nbsp;"><node CREATED="1747229394309" ID="ID_e8d4622a3613b8dc" MODIFIED="1747229394309" TEXT="操作一个流的标准步骤"></node><node CREATED="1747229394309" ID="ID_5bc3709e8249bec5" MODIFIED="1747229394309" TEXT="1.打开流"></node><node CREATED="1747229394309" ID="ID_383ae0da8d582108" MODIFIED="1747229394309" TEXT="2.判断。&amp;nbsp;判断是否为NULL"></node><node CREATED="1747229394309" ID="ID_3379c0c370390f51" MODIFIED="1747229394309" TEXT="3.使用"></node><node CREATED="1747229394309" ID="ID_2dad66ee01366dd4" MODIFIED="1747229394309" TEXT="4.关闭流"></node></node></node><node CREATED="1747229394309" ID="ID_50c6233b92d429a4" POSITION="right" MODIFIED="1747229394309" TEXT="系统编程"><node CREATED="1747229394309" ID="ID_a300dd310741cf30" MODIFIED="1747229394309" TEXT="系统调用是什么"></node><node CREATED="1747229394309" ID="ID_30b0e57a43c6d4a1" MODIFIED="1747229394309" TEXT="库函数得知道"><node CREATED="1747229394309" ID="ID_58ad255630cc9267" MODIFIED="1747229394309" TEXT="ISO-C"></node><node CREATED="1747229394309" ID="ID_35ee24ea0edf9cb8" MODIFIED="1747229394309" TEXT="POSIX-C"></node><node CREATED="1747229394309" ID="ID_0b6af23275d675b9" MODIFIED="1747229394309" TEXT="这两个名词的含义，&amp;nbsp;以及它们谁更通用。&amp;nbsp;"></node></node><node CREATED="1747229394309" ID="ID_d0e807617f116b26" MODIFIED="1747229394309" TEXT="shell得知道一下"></node><node CREATED="1747229394309" ID="ID_c460708aceca45c0" MODIFIED="1747229394309" TEXT="知道这几者的关系，然后怎么选也要知道一下"></node><node CREATED="1747229394309" ID="ID_b4d88bdbeca7f476" MODIFIED="1747229394309" TEXT="学习顺序"><node CREATED="1747229394309" ID="ID_6612fe81d46e5dcb" MODIFIED="1747229394309" TEXT="会先学习文件系统编程，&amp;nbsp;后续是进程和线程，最后是网络"></node><node CREATED="1747229394309" ID="ID_cae008a08c2089a2" MODIFIED="1747229394309" TEXT="因为Linux里面，一切皆文件。学会了文件操作，后续的很多操作都是通的。"></node></node><node CREATED="1747229394309" ID="ID_8466847fbb5b519d" MODIFIED="1747229394309" TEXT="学习的方法"><node CREATED="1747229394309" ID="ID_365fdd343cca67e0" MODIFIED="1747229394309" TEXT="因为系统编程这块，会学习大量的函数。&amp;nbsp;强行记下所有的函数名，入参和返回值不现实。建议大家的学习方式如下"></node><node CREATED="1747229394309" ID="ID_65ce5525f01412f0" MODIFIED="1747229394309" TEXT="1.首先函数名要记住，函数的大致功能要记住"><node CREATED="1747229394309" ID="ID_f67c147af9044a3d" MODIFIED="1747229394309" TEXT="这两点主要是让大家在碰到一个功能的时候，能想到一个函数。&amp;nbsp;&amp;lt;br&amp;gt;后续入参、返回值。可以用到的时候现查。基本就是按照简明知意"></node></node><node CREATED="1747229394309" ID="ID_29aa8c0ffd22b098" MODIFIED="1747229394309" TEXT="2.man手册的三卷要记住。 1卷就是shell命令，2卷就是系统调用，3卷就是库函数"></node><node CREATED="1747229394309" ID="ID_8af50c63f0d3dacf" MODIFIED="1747229394309" TEXT="3.如果忘了，直接查man手册"><node CREATED="1747229394309" ID="ID_b2e98d14f923fdcb" MODIFIED="1747229394309" TEXT="先看名字，这块一般是函数的主体功能"></node><node CREATED="1747229394309" ID="ID_fd6fc8c13dead5a6" MODIFIED="1747229394309" TEXT="然后看描述，这块会说函数的头文件，紧接着看函数的声明。&amp;nbsp;&amp;lt;br&amp;gt;看函数声明的时候，基本看参数的名字就可以知道要传啥"></node><node CREATED="1747229394309" ID="ID_85ad5c6faacdb609" MODIFIED="1747229394309" TEXT="返回值和参数的规律问题"><node CREATED="1747229394309" ID="ID_97797525c5f2c6e2" MODIFIED="1747229394309" TEXT="返回值的问题"><node CREATED="1747229394309" ID="ID_16150321f6d68ae6" MODIFIED="1747229394309" TEXT="C语言没有错误处理。&amp;nbsp;它的错误提示基本都通过返回值告诉你。&amp;nbsp;&amp;lt;br&amp;gt;"><node CREATED="1747229394309" ID="ID_08bb17d163a4aadd" MODIFIED="1747229394309" TEXT="返回值一般兼具两个任务。&amp;nbsp;一个是正常的返回值。&amp;nbsp;&amp;lt;br&amp;gt;另外一个通过返回值告诉你函数调用出错了"></node></node><node CREATED="1747229394309" ID="ID_94d4a6eb882c622c" MODIFIED="1747229394309" TEXT="返回值有两种可能"><node CREATED="1747229394309" ID="ID_c539ca009f393883" MODIFIED="1747229394309" TEXT="基本数据类型"><node CREATED="1747229394309" ID="ID_efc6dbc4f47513a0" MODIFIED="1747229394309" TEXT="一般情况下，返回-1，表示出错了。 &amp;lt;br&amp;gt;这时候只知道它出错，但是不知道错误的具体信息。 &amp;lt;br&amp;gt;所以这时候，一般系统会将错误信息，塞到errno里面。&amp;lt;br&amp;gt;perror就可以直接打印出来信息&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229394309" ID="ID_8a01314c019a8634" MODIFIED="1747229394309" TEXT="指针类型"><node CREATED="1747229394309" ID="ID_9ef7a70b70a113d0" MODIFIED="1747229394309" TEXT="返回结构体指针，或者其他指针。&amp;nbsp;&amp;lt;br&amp;gt;这时候错误了，会返回NULL"></node></node><node CREATED="1747229394309" ID="ID_6247c4cbea5ac113" MODIFIED="1747229394309" TEXT="所以一般情况下，先检查返回值是不是-1/ NULL&amp;lt;br&amp;gt;如果返回值是-1，perror打印错误信息"></node></node></node><node CREATED="1747229394309" ID="ID_9a11b420f812ffd8" MODIFIED="1747229394309" TEXT="参数问题"><node CREATED="1747229394309" ID="ID_83695c349b509b26" MODIFIED="1747229394309" TEXT="对指针的参数。&amp;lt;br&amp;gt;test1(const char *str)&amp;lt;br&amp;gt;test1(char *str)&amp;lt;br&amp;gt;"></node><node CREATED="1747229394309" ID="ID_f93171dcfca308a8" MODIFIED="1747229394309" TEXT="一般指针参数，如果加了const。&amp;nbsp;就意味着这个参数不会被修改。&amp;lt;br&amp;gt;这个参数是一个只读参数"></node><node CREATED="1747229394309" ID="ID_27cdd228d746d84a" MODIFIED="1747229394309" TEXT="如果没加const。大概率会被改掉。&amp;nbsp;&amp;lt;br&amp;gt;这时候比如需要的是某个结构体的指针。这时候指针一定要指向有效的内存，不然会报错"></node><node CREATED="1747229394309" ID="ID_c1f16a58ac67e1ab" MODIFIED="1747229394309" TEXT="如果一个指针参数，有无const修饰。&amp;lt;br&amp;gt;其实说明了这个参数的作用"><node CREATED="1747229394309" ID="ID_d609ded5f8592089" MODIFIED="1747229394309" TEXT="如果有const修饰，这个参数就是给别人读取一下的（不会修改你）"></node><node CREATED="1747229394309" ID="ID_678dded83f4ae22e" MODIFIED="1747229394309" TEXT="如果没有const修饰，这个参数承担了信息传递的任务。&amp;nbsp;"></node><node CREATED="1747229394309" ID="ID_4aafeca8213e890a" MODIFIED="1747229394309" TEXT="这个指针，一定是指向有效内存的。&amp;nbsp;"></node></node><node CREATED="1747229394309" ID="ID_78ea46e863a7409e" MODIFIED="1747229394309" TEXT="看参数的名字，可以知道参数的大致作用。"></node></node></node><node CREATED="1747229394309" ID="ID_64a844d80f2aa0ba" MODIFIED="1747229394309" TEXT="重点：&amp;nbsp;记住函数名、函数的功能。&amp;lt;br&amp;gt;剩下的（参数、返回值、头文件）碰到了再通过man手册查&amp;lt;br&amp;gt;"></node></node></node><node CREATED="1747229394309" ID="ID_a63e804c74ed4f84" MODIFIED="1747229394309" TEXT="目录相关的系统调用"><node CREATED="1747229394309" ID="ID_b31e6ef2a1767995" MODIFIED="1747229394309" TEXT="chmod"><node CREATED="1747229394309" ID="ID_d8f2050108bf049f" MODIFIED="1747229394309" TEXT="改变权限"></node><node CREATED="1747229394309" ID="ID_259adf66730d4889" MODIFIED="1747229394309" TEXT="int chmod(const char *pathname, mode_t mode);"></node></node><node CREATED="1747229394309" ID="ID_e7604458fff3713e" MODIFIED="1747229394309" TEXT="怎么去查看类型别名的具体定义"><node CREATED="1747229394309" ID="ID_c710e9f94cd94afd" MODIFIED="1747229394309" TEXT="在Linux阶段，基本很多东西都是类型别名，所以需要知道如何查看类型别名的具体类型"></node><node CREATED="1747229394309" ID="ID_d918f7cdcc3eac28" MODIFIED="1747229394309" TEXT="建议使用预处理指令。预处理之后，可以搜索。&amp;nbsp;"><node CREATED="1747229394309" ID="ID_2932ef0738ec8c43" MODIFIED="1747229394309" TEXT="gcc -E test1.c -o test1.i"></node><node CREATED="1747229394309" ID="ID_f818580189a5ec53" MODIFIED="1747229394309" TEXT="vim&amp;nbsp;打开。&amp;nbsp;&amp;lt;br&amp;gt;然后使用 /&amp;nbsp;来搜索。&amp;lt;br&amp;gt;n是跳到下一个匹配项。 N是上一个"></node></node><node CREATED="1747229394309" ID="ID_3238905e0bcea00c" MODIFIED="1747229394309" TEXT="grep命令可以搜索。&amp;nbsp;搜索的时候建议默认加上 -nE&amp;nbsp;"><node CREATED="1747229394309" ID="ID_a0caa3f6b5d93575" MODIFIED="1747229394309" TEXT="grep -nE &amp;quot;mode_t&amp;quot; test2.i&amp;lt;br&amp;gt;"></node><node CREATED="1747229394309" ID="ID_2d12bb296b01e36b" MODIFIED="1747229394309" TEXT="-C&amp;nbsp;搜索的时候，顺便显示一下上下的行。&amp;nbsp;&amp;lt;br&amp;gt;-C10&amp;nbsp;顺便显示一下上下"></node><node CREATED="1747229394309" ID="ID_5098a0e27fde927b" MODIFIED="1747229394309" TEXT="因为结构体，有时候是想看结构体的具体内容。&amp;nbsp;所以可以让它显示一下上下的内容，&amp;lt;br&amp;gt;方便看结构体里面的具体属性"></node><node CREATED="1747229394309" ID="ID_2f666bc4f3707086" MODIFIED="1747229394309" TEXT="如果想搜索一个结构体长什么样。&amp;nbsp;&amp;lt;br&amp;gt;&amp;nbsp;grep -nE &amp;quot;FILE&amp;quot; test3_chmod.i&amp;lt;br&amp;gt;从这里，可以知道行号。&amp;nbsp;通过vim打开，跳到指定行。&amp;nbsp;"></node><node CREATED="1747229394309" ID="ID_e44dd34f4854346a" MODIFIED="1747229394309" TEXT="-C10&amp;nbsp;上下多展示几行"></node></node><node CREATED="1747229394309" ID="ID_e22e5cd60e4feac9" MODIFIED="1747229394309" TEXT="应该掌握如何查看一个类型别名的真实类型的&amp;lt;br&amp;gt;掌握如何查看一个结构体的字段。&amp;nbsp;"></node></node><node CREATED="1747229394309" ID="ID_c6395c13f94c474a" MODIFIED="1747229394309" TEXT="chdir"><node CREATED="1747229394309" ID="ID_7bad89d2deb2ec0d" MODIFIED="1747229394309" TEXT="改变当前工作目录。&amp;nbsp;"></node></node><node CREATED="1747229394309" ID="ID_5e354c61a8e3f658" MODIFIED="1747229394309" TEXT="getcwd"><node CREATED="1747229394309" ID="ID_25b351b6c934f9e0" MODIFIED="1747229394309" TEXT="获取当前工作目录"></node></node><node CREATED="1747229394309" ID="ID_998832d3bd3542db" MODIFIED="1747229394309" TEXT="mkdir"><node CREATED="1747229394309" ID="ID_63bb2c1928d16d45" MODIFIED="1747229394309" TEXT="创建目录"></node></node><node CREATED="1747229394309" ID="ID_7c45a8bc008cdc2b" MODIFIED="1747229394309" TEXT="rmdir"><node CREATED="1747229394309" ID="ID_674093619a5c70fd" MODIFIED="1747229394309" TEXT="删除目录"></node></node><node CREATED="1747229394309" ID="ID_e8dc340fa4bf5b3a" MODIFIED="1747229394309" TEXT="对于后续的学习来说，一定要学会用man命令。&amp;nbsp;"><node CREATED="1747229394309" ID="ID_8a8e91a85d431caf" MODIFIED="1747229394309" TEXT="也可以直接看函数的形参名。&amp;nbsp;"></node><node CREATED="1747229394309" ID="ID_67db96c68cdf369b" MODIFIED="1747229394309" TEXT="为什么我不显示提示vim下面的提示。&amp;nbsp;写完函数名之后，下，选一下它。然后写括号就有了。&amp;lt;br&amp;gt;实在不行也可以截图，钉在这。&amp;nbsp;&amp;nbsp;"></node></node></node><node CREATED="1747229394309" ID="ID_930c4b7378bf90fe" MODIFIED="1747229394309" TEXT="目录流相关函数"><node CREATED="1747229394309" ID="ID_ad0b83d74f455e32" MODIFIED="1747229394309" TEXT="打开目录流 opendir"></node><node CREATED="1747229394309" ID="ID_ee0f61029abbe8b8" MODIFIED="1747229394309" TEXT="关闭目录流 closedir"></node><node CREATED="1747229394309" ID="ID_20129ebf9d90ceb7" MODIFIED="1747229394309" TEXT="读取目录流 readdir"><node CREATED="1747229394309" ID="ID_6ac3cdf3d30ef5d2" MODIFIED="1747229394309" TEXT="struct dirent *readdir(DIR *dirp);"></node><node CREATED="1747229394309" ID="ID_48c6fba242bed1ef" MODIFIED="1747229394309" TEXT="传入的DIR指针，就是从打开目录流着捞到的。&amp;nbsp;"></node><node CREATED="1747229394309" ID="ID_e0f9651cb7b96aaa" MODIFIED="1747229394309" TEXT="返回的是一个 struct dirent *的指针。我们不需要做内存的释放动作，也就是不要free。&amp;nbsp;系统自己会搞定这个事情"></node><node CREATED="1747229394309" ID="ID_30a9bc55a9a99bf5" MODIFIED="1747229394309" TEXT="结构体里面的东西，有哪些需要关注"><node CREATED="1747229394309" ID="ID_c7f80e8c159637d9" MODIFIED="1747229394309" TEXT="&amp;nbsp;ino_t d_ino"><node CREATED="1747229394309" ID="ID_316b958b9d27ba01" MODIFIED="1747229394309" TEXT="typedef unsigned long int __ino_t;&amp;lt;br&amp;gt;这个是从.i文件里捞到的"></node></node><node CREATED="1747229394309" ID="ID_268c43a554337b17" MODIFIED="1747229394309" TEXT="d_type :&amp;nbsp;就是文件的类型，是靠一个数字来标识一种类型。&amp;lt;br&amp;gt;比如 1表示文件，2表示目录，4表示其他的。。。"><node CREATED="1747229394309" ID="ID_2333d08e0c95ab4f" MODIFIED="1747229394309" TEXT="这些数字不用记，使用宏定义去做判断"></node></node><node CREATED="1747229394309" ID="ID_3748184736b85667" MODIFIED="1747229394309" TEXT="d_name:&amp;nbsp;就是文件的名字。"></node></node></node><node CREATED="1747229394309" ID="ID_1d59712b5248be64" MODIFIED="1747229394309" TEXT="假设，想自己实现ls。&amp;nbsp; ls -al"><node CREATED="1747229394309" ID="ID_a813f744f6980bda" MODIFIED="1747229394309" TEXT="现在有什么信息？"></node><node CREATED="1747229394309" ID="ID_73881037d4e6a00a" MODIFIED="1747229394309" TEXT="inode编号&amp;lt;br&amp;gt;type&amp;nbsp;类型&amp;lt;br&amp;gt;name&amp;nbsp;名字"></node></node></node><node CREATED="1747229394309" ID="ID_20ec5e0f20374952" MODIFIED="1747229394309" TEXT="stat"><node CREATED="1747229394309" ID="ID_d16738d04b29a5ec" MODIFIED="1747229394309" TEXT="获取详细信息的函数"></node><node CREATED="1747229394309" ID="ID_e2a876ee4608e80a" MODIFIED="1747229394309" TEXT="int stat(const char *path, struct stat *buf);"><node CREATED="1747229394309" ID="ID_a7dceb894e1f1cd5" MODIFIED="1747229394309" TEXT="第一个参数是路径。&amp;nbsp;可以是相对路径，可以是绝对路径"></node><node CREATED="1747229394309" ID="ID_774faf455d3a85cb" MODIFIED="1747229394309" TEXT="第二个参数是结构体指针，没有const修饰。&amp;nbsp;其实就是用来存储stat获取的&amp;lt;br&amp;gt;详细信息的"></node></node><node CREATED="1747229394309" ID="ID_04605ed74eed03ec" MODIFIED="1747229394309" TEXT="stat结构体中能够提供的信息"><node CREATED="1747229394309" ID="ID_f9c24e46b25e1744" MODIFIED="1747229394309" TEXT="st_mode:&amp;nbsp;类型&amp;amp;权限"></node><node CREATED="1747229394309" ID="ID_eeea4bfb6fa00b37" MODIFIED="1747229394309" TEXT="st_nlink：&amp;nbsp;硬链接数"></node><node CREATED="1747229394309" ID="ID_b4a5940000dae00d" MODIFIED="1747229394309" TEXT="st_uid：&amp;nbsp;文件的所有者用户id"></node><node CREATED="1747229394309" ID="ID_e1420f1eb1016fa4" MODIFIED="1747229394309" TEXT="st_gid:&amp;nbsp;文件所有者组id"></node><node CREATED="1747229394309" ID="ID_902b8731139d0432" MODIFIED="1747229394309" TEXT="st_size：&amp;nbsp;文件的大小"></node><node CREATED="1747229394309" ID="ID_963add8ffaf9d2ad" MODIFIED="1747229394309" TEXT="st_mtim：&amp;nbsp;最后修改时间。&amp;nbsp;结构体。里面有秒值&amp;amp;纳秒值&amp;nbsp;"></node><node CREATED="1747229394309" ID="ID_c05caa947b6add87" MODIFIED="1747229394309" TEXT="stat获取的信息中，少了 name !"></node></node><node CREATED="1747229394309" ID="ID_a19b6183228b453d" MODIFIED="1747229394309" TEXT="现在，我们能够打印出来一些比较初级的信息。&amp;nbsp;&amp;lt;br&amp;gt;printf(&amp;quot;%o %lu %d %d %ld %ld&amp;quot;, buf_p-&amp;gt;st_mode, buf_p-&amp;gt;st_nlink, buf_p-&amp;gt;st_uid, buf_p-&amp;gt;st_gid,&amp;lt;br&amp;gt;buf_p-&amp;gt;st_size, buf_p-&amp;gt;st_mtim.tv_sec);&amp;lt;br&amp;gt;"><node CREATED="1747229394309" ID="ID_4cfc2c1133f60d62" MODIFIED="1747229394309" TEXT="大家晚上的时候。到当前步骤一定要能写出来。&amp;nbsp;"></node><node CREATED="1747229394309" ID="ID_14ae4beb8b74ff06" MODIFIED="1747229394309" TEXT="如果后续的转换过程代码能写出来更好，写不出来先不要着急"></node><node CREATED="1747229394309" ID="ID_ee993f5e899d4c04" MODIFIED="1747229394309" TEXT="类型的转换。&amp;nbsp; st_mode&amp;nbsp; -&amp;gt; - d c&amp;nbsp;&amp;lt;br&amp;gt;权限的转换 664&amp;nbsp; &amp;nbsp;--&amp;gt; rw-rw-r--"></node><node CREATED="1747229394309" ID="ID_fa38840cf722b461" MODIFIED="1747229394309" TEXT="uid, gid&amp;nbsp;转换为了对应的名字"></node><node CREATED="1747229394309" ID="ID_27c9598d9c4cbfec" MODIFIED="1747229394309" TEXT="时间戳，转换为了&amp;nbsp;年月日，时分这些信息"></node><node CREATED="1747229394309" ID="ID_2818165f6a6378ef" MODIFIED="1747229394309" TEXT="底下三个转换能写出来更好"></node><node CREATED="1747229394309" ID="ID_c251f856eaa964f8" MODIFIED="1747229394309" TEXT="提升：&amp;nbsp;继续写排序的"><node CREATED="1747229394309" ID="ID_9fdfcc63d98102b4" MODIFIED="1747229394309" TEXT="readdir&amp;nbsp;可以拿到一个一个的名字。&amp;lt;br&amp;gt;申请内存，然后将字符串存起来。&amp;nbsp;&amp;lt;br&amp;gt;指针数组。&amp;nbsp;存起来所有的。&amp;nbsp;&amp;lt;br&amp;gt;&amp;nbsp;可以将所有的名字都存储到指针数组里面。&amp;nbsp;&amp;nbsp;"></node><node CREATED="1747229394309" ID="ID_533a9fb10b6aaa05" MODIFIED="1747229394309" TEXT="qsort。&amp;nbsp;数组塞进去、大小（sizeof(char *)）、函数指针"></node></node><node CREATED="1747229394309" ID="ID_35411e2a857763dc" MODIFIED="1747229394309" TEXT="实现一下tree"></node></node><node CREATED="1747229394309" ID="ID_b0a15af9be7073d2" MODIFIED="1747229394309" TEXT="信息一定要知道从哪里来，后续在业务中。&amp;lt;br&amp;gt;要用到这些信息的时候，从什么函数中获取它。"></node></node></node></node></map>